UPDATE tclubshistoricos SET Nombre='Lumynid Esports' WHERE LOWER(TRIM(Nombre))=LOWER('Lumyind Esports');
-- Normaliza nombres anteriores; solo retira duplicados nuevos sin estadísticas.
DELETE c FROM tclubshistoricos c JOIN tclubshistoricos old ON LOWER(TRIM(old.Nombre)) = LOWER('Last Five Stars Cosmos') WHERE LOWER(TRIM(c.Nombre)) = LOWER('LSS Cosmos') AND COALESCE(c.Puntuacion,0)=0 AND COALESCE(c.PartidosGanados,0)=0 AND COALESCE(c.PartidosPerdidos,0)=0;
UPDATE tclubshistoricos c LEFT JOIN (SELECT Nombre FROM (SELECT Nombre FROM tclubshistoricos) names_snapshot WHERE LOWER(TRIM(Nombre))=LOWER('LSS Cosmos')) existing ON 1=1 SET c.Nombre='LSS Cosmos' WHERE LOWER(TRIM(c.Nombre))=LOWER('Last Five Stars Cosmos') AND existing.Nombre IS NULL;
